-- definidos no modelo lógico v1.0.0 (seção 4.3). Os códigos são os do LEDI, nunca a
-- posição da opção na ficha. Execute depois de 01_ddl e antes de qualquer outra carga.
-- dom_tipo_unidade e dom_tipo_equipe são carregadas na Etapa 5, a partir do CNES.
-- =====================================================================

